"use client";

import { Minus, Plus, X, Heart } from "lucide-react";
import { BagItem } from "@/data/bagItems";

interface BagItemCardProps {
  item: BagItem;
}

export default function BagItemCard({ item }: BagItemCardProps) {
  return (
    <div className="group relative flex flex-row gap-8 py-10 border-b border-border last:border-0 transition-all">
      {/* 1. Large Image with Premium Aspect Ratio */}
      <div className="w-[40vw] aspect-3/3 relative shrink-0">
        <img
          src={item.image}
          alt={item.name}
          className={`object-cover object-center rounded-3xl transition-transform duration-1000 ease-out group-hover:scale-105 ${
            !item.inStock ? "opacity-40 grayscale" : ""
          }`}
        />
      </div>

      {/* 2. Main Content Area */}
      <div className="flex-1 flex flex-col justify-between">
        {/* Top Section: Title and Price */}
        <div className="flex flex-col justify-between items-start gap-4">
          <div className="space-y-1.5">
            <h3 className="text-xl font-medium text-foreground leading-tight tracking-tight max-w-[280px]">
              {item.name}
            </h3>
            <div className="flex items-center gap-3 text-[12px] text-foreground-subtle uppercase tracking-[0.15em] font-medium">
              <span>{item.color}</span>
              <span className="h-3 w-[1px] bg-border" />
              <span>{item.size}</span>
            </div>
          </div>

          <div className="text-right flex items-end">
            <div className="flex justify-center items-center gap-4">
              {item.originalPrice && (
                <span className="text-foreground-subtle line-through opacity-60 tabular-nums">
                  ₹{item.originalPrice.toLocaleString()}
                </span>
              )}
              <span className="font-semibold tracking-tight tabular-nums">
                ₹{(item.price * item.quantity).toLocaleString()}
              </span>
            </div>
          </div>
        </div>

        {/* Bottom Section: Integrated Controls & Actions */}
        <div className="mt-8 flex flex-col sm:flex-row sm:items-center justify-between gap-6">
          {/* Enhanced Quantity Controller */}
          <div className="flex items-center w-fit border border-border rounded-sm overflow-hidden bg-background shadow-sm">
           <div>
            
           </div>
            <button
              className="flex ml-4 items-center justify-center p-3 border border-border text-foreground-subtle hover:text-destructive hover:border-destructive transition-all duration-300 cursor-pointer group/del"
              aria-label="Remove item"
            >
              <X
                size={18}
                strokeWidth={1.5}
                className="group-hover/del:scale-110 transition-transform"
              />
            </button>
          </div>

          {/* Unified Action Buttons Row */}
          <div className="flex items-center gap-2">
            <button className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-6 py-3 border border-border text-foreground text-[11px] font-bold uppercase tracking-[0.1em] hover:border-foreground hover:bg-foreground hover:text-background transition-all duration-300 cursor-pointer">
              <Heart size={14} />
              Move to Wishlist
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
